package org.example.spotifymixer.testhost;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.media.session.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import androidx.test.core.app.ActivityScenario;import org.junit.*;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.*;import org.example.spotifymixer.runtime.*;
/** Only original fixture sessions/data. No Spotify, account, network or audible playback. */
@org.junit.runner.RunWith(AndroidJUnit4.class)
public class EnhancementTest {
 private final Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();private final UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());
 private final SharedPreferences prefs=context.getSharedPreferences("spotify-mixer-entry-v1",0);
 private final String ONE="spotify:track:0000000000000000000001",TWO="spotify:track:0000000000000000000002";
 private void idle(){InstrumentationRegistry.getInstrumentation().waitForIdleSync();device.waitForIdle();}
 private void until(java.util.function.BooleanSupplier check){long end=SystemClock.uptimeMillis()+6000;do{idle();if(check.getAsBoolean())return;SystemClock.sleep(50);}while(SystemClock.uptimeMillis()<end);assertTrue(check.getAsBoolean());}
 private UiObject2 text(String title)throws Exception{device.waitForIdle();UiObject2 found=device.wait(Until.findObject(By.text(title)),3000);if(found==null||found.getVisibleBounds().isEmpty()){if(device.hasObject(By.clazz("android.widget.ScrollView")))new UiScrollable(new UiSelector().className("android.widget.ScrollView")).scrollTextIntoView(title);found=device.wait(Until.findObject(By.text(title)),3000);}assertNotNull(title,found);return found;}
 private void dialog(boolean positive){UiObject2 button=device.wait(Until.findObject(By.res(positive?"android:id/button1":"android:id/button2")),4000);assertNotNull(button);button.click();idle();}
 private void open(String id){context.startActivity(new Intent(context,SpotEnhancerActivity.class).putExtra("screen","tool:"+id).putExtra("from_spotify",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));idle();}
 private void shot(String name)throws Exception{idle();String base="/sdcard/Download/spotenhancer-evidence/";device.executeShellCommand("mkdir -p "+base);device.executeShellCommand("screencap -p "+base+name+".png");}
 private MediaSession fixture(AtomicLong sought,AtomicInteger pauses,AtomicInteger skips){MediaSession s=new MediaSession(context,"Own enhancement fixture");s.setPlaybackToLocal(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).build());s.setFlags(MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);s.setCallback(new MediaSession.Callback(){public void onPause(){pauses.incrementAndGet();state(s,PlaybackState.STATE_PAUSED);}public void onPlay(){state(s,PlaybackState.STATE_PLAYING);}public void onSeekTo(long pos){sought.set(pos);}public void onSkipToNext(){skips.incrementAndGet();}public void onSkipToQueueItem(long id){sought.set(id);}},new Handler(Looper.getMainLooper()));Bitmap bitmap=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xff27599c);s.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_MEDIA_ID,ONE).putString(MediaMetadata.METADATA_KEY_TITLE,"Own fixture song").putString(MediaMetadata.METADATA_KEY_ARTIST,"Original fixture artist").putLong(MediaMetadata.METADATA_KEY_DURATION,180000).putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,bitmap).build());s.setQueue(Arrays.asList(new MediaSession.QueueItem(new MediaDescription.Builder().setMediaId(ONE).setTitle("Alpha fixture track").setSubtitle("Artist A").build(),1),new MediaSession.QueueItem(new MediaDescription.Builder().setMediaId(TWO).setTitle("Beta fixture track").setSubtitle("Artist B").build(),2)));state(s,PlaybackState.STATE_PAUSED);s.setActive(true);return s;}
 private void state(MediaSession s,int state){s.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SKIP_TO_QUEUE_ITEM).setState(state,5000,state==PlaybackState.STATE_PLAYING?1:0,SystemClock.elapsedRealtime()).build());}
 @Before public void before(){prefs.edit().clear().commit();MediaToolsRuntime.attach(context);idle();}
 @After public void after(){prefs.edit().clear().commit();MediaToolsRuntime.cancelTimer();EqualizerRuntime.refresh();ThemeRuntime.refresh(context);EnhancementRuntime.refresh();device.pressHome();}
 @Test public void optionalSettingsAndProfilesExcludeTransactionData()throws Exception{
  open("volume");assertFalse(text("Enable Volume Steps").isChecked());assertNull(device.findObject(By.text("Save volume steps")));text("Enable Volume Steps").click();until(()->prefs.getBoolean("volume_enabled",false));UiObject2 input=device.wait(Until.findObject(By.desc("Volume steps (1–10)")),3000);assertNotNull(input);input.setText("4");text("Save volume steps").click();until(()->prefs.getInt("volume_steps",0)==4);
  prefs.edit().putString("creator_pending","sensitive fixture operation").putString("queue_snapshot","fixture queue").commit();open("profiles");text("Enable Settings Profiles").click();until(()->prefs.getBoolean("profiles_enabled",false));UiObject2 name=device.wait(Until.findObject(By.desc("Settings profile name")),3000);assertNotNull(name);name.setText("Night fixture");text("Save settings profile").click();until(()->prefs.getString("settings_profiles","").contains("Night fixture"));assertFalse(prefs.getString("settings_profiles","").contains("sensitive fixture operation"));assertFalse(prefs.getString("settings_profiles","").contains("fixture queue"));prefs.edit().putInt("volume_steps",1).commit();text("Apply profile").click();dialog(true);until(()->prefs.getInt("volume_steps",0)==4);assertEquals("sensitive fixture operation",prefs.getString("creator_pending",""));shot("16-settings-profiles-own-fixture");
  open("confirm_clear");assertFalse(text("Enable Confirm Queue Clear").isChecked());assertFalse(prefs.getBoolean("confirm_clear_enabled",false));assertNull(device.findObject(By.text("Review upcoming queue")));
 }
 @Test public void realOwnSessionDrivesCinemaQueueSearchAndSleep()throws Exception{
  AtomicLong sought=new AtomicLong(-1);AtomicInteger pauses=new AtomicInteger(),skips=new AtomicInteger();MediaSession s=fixture(sought,pauses,skips);
  try{MediaToolsRuntime.captureSession(s);until(()->ONE.equals(MediaToolsRuntime.currentTrack()));prefs.edit().putBoolean("cinema_enabled",true).putBoolean("artwork_enabled",true).putBoolean("seek_enabled",true).putBoolean("skip_guard_enabled",false).commit();open("cinema");text("Own fixture song");UiObject2 seekButton=device.wait(Until.findObject(By.desc("Seek forward 10 seconds")),4000);assertNotNull(seekButton);seekButton.click();until(()->sought.get()==15000);text("Next").click();until(()->skips.get()==1);shot("17-cinema-live-artwork-own-fixture");
   prefs.edit().putBoolean("queue_search_enabled",true).commit();open("queue_search");text("Alpha fixture track");UiObject2 search=device.findObject(By.desc("Search published queue"));assertNotNull(search);search.setText("Beta");text("Beta fixture track");assertNull(device.findObject(By.text("Alpha fixture track")));text("Play this queue item").click();until(()->sought.get()==2);shot("18-queue-search-own-fixture");
   prefs.edit().putBoolean("queue_undo_enabled",true).commit();open("queue_undo");text("Save published queue snapshot").click();until(()->prefs.getString("queue_snapshot","").contains("0000000000000000000002"));assertEquals(2,MediaToolsRuntime.savedQueue().size());
   prefs.edit().putBoolean("sleep_enabled",true).commit();MediaToolsRuntime.startTimer(1);assertTrue(MediaToolsRuntime.remaining()>0);MediaToolsRuntime.cancelTimer();assertEquals(0,MediaToolsRuntime.remaining());MediaToolsRuntime.startTimer(1);java.lang.reflect.Field due=MediaToolsRuntime.class.getDeclaredField("deadline");due.setAccessible(true);due.setLong(null,SystemClock.elapsedRealtime()-1);java.lang.reflect.Method fire=MediaToolsRuntime.class.getDeclaredMethod("fireTimer");fire.setAccessible(true);fire.invoke(null);until(()->pauses.get()==1);assertEquals(0,MediaToolsRuntime.remaining());
   prefs.edit().putBoolean("clean_share_enabled",true).commit();open("clean_share");text("Copy clean Spotify link").click();idle();ClipData clip=((ClipboardManager)context.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip();assertNotNull(clip);assertEquals("https://open.spotify.com/track/0000000000000000000001",clip.getItemAt(0).getText().toString());
  }finally{s.release();idle();}
 }
 @Test public void duplicateScannerReadsOwnProtocolWithoutMutation()throws Exception{
  CreatorProtocolFixture.writes=0;CreatorProtocolFixture.name="Duplicate fixture playlist";CreatorProtocolFixture.wrongReadback=false;CreatorProtocolFixture.tracks=new ArrayList<>(Arrays.asList(ONE,ONE,TWO));NativeBridge.capturePlaylist(new CreatorProtocolFixture());prefs.edit().putBoolean("duplicates_enabled",true).commit();
  try{context.startActivity(new Intent(context,SpotEnhancerActivity.class).putExtra("screen","tool:duplicates").putExtra("playlist","spotify:playlist:0000000000000000000001").putExtra("title","Duplicate fixture playlist").putExtra("from_spotify",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));idle();text("Scan for duplicates").click();text("3 rows checked · 1 repeated track IDs");assertEquals(0,CreatorProtocolFixture.writes);shot("19-duplicates-own-protocol-fixture");}finally{NativeBridge.capturePlaylist(null);}
 }
 @Test public void nativeQueueAdapterConfirmsOneWriteAndRecoversByReads()throws Exception{
  QueueProtocolFixture.reset();NativeBridge.capturePlayer(new QueueProtocolFixture());NativeBridge.capturePlaylist(new CreatorProtocolFixture());MediaSession media=fixture(new AtomicLong(),new AtomicInteger(),new AtomicInteger());
  try{MediaToolsRuntime.captureSession(media);until(()->ONE.equals(MediaToolsRuntime.currentTrack()));prefs.edit().putBoolean("confirm_clear_enabled",true).commit();open("confirm_clear");text("Review upcoming queue").click();text("2 upcoming items · 1 previous items");text("Clear upcoming queue…").click();dialog(false);assertEquals(0,QueueProtocolFixture.writes);text("Clear upcoming queue…").click();dialog(true);until(()->QueueProtocolFixture.writes==1&&!prefs.contains("queue_clear_pending"));text("Upcoming native queue verified empty. No play command was sent.");assertEquals(0,QueueProtocolFixture.read().nextTracks().size());assertEquals(1,QueueProtocolFixture.read().prevTracks().size());shot("20-native-queue-clear-own-protocol");
   QueueProtocolFixture.reset();QueueProtocolFixture.missingAck=true;QueueClearSession session=NativeQueue.session(prefs);try{session.clear(session.preview());fail();}catch(java.io.IOException expected){}assertTrue(prefs.contains("queue_clear_pending"));assertEquals(1,QueueProtocolFixture.writes);NativeQueue.session(prefs).verify();assertFalse(prefs.contains("queue_clear_pending"));assertEquals(1,QueueProtocolFixture.writes);
  }finally{NativeBridge.capturePlayer(null);NativeBridge.capturePlaylist(null);media.release();idle();}
 }
 @Test public void transformedOwnDexCapturesRealFrameworkSession()throws Exception{
  String name="Lp/bqf0;";java.util.List<org.jf.dexlib2.iface.Method> constructors=new ArrayList<>();org.jf.dexlib2.immutable.reference.ImmutableFieldReference field=new org.jf.dexlib2.immutable.reference.ImmutableFieldReference(name,"a","Landroid/media/session/MediaSession;");
  for(java.util.List<String> params:Arrays.asList(Arrays.asList("Landroid/content/Context;","Ljava/lang/String;"),Collections.singletonList("Landroid/media/session/MediaSession;"))){int self=10-params.size()-1;java.util.List<org.jf.dexlib2.immutable.ImmutableMethodParameter> args=new ArrayList<>();for(String arg:params)args.add(new org.jf.dexlib2.immutable.ImmutableMethodParameter(arg,Collections.emptySet(),null));java.util.List<org.jf.dexlib2.iface.instruction.Instruction> ins=new ArrayList<>();ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction35c(org.jf.dexlib2.Opcode.INVOKE_DIRECT,1,self,0,0,0,0,new org.jf.dexlib2.immutable.reference.ImmutableMethodReference("Ljava/lang/Object;","<init>",Collections.emptyList(),"V")));
   if(params.size()==2){ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction21c(org.jf.dexlib2.Opcode.NEW_INSTANCE,0,new org.jf.dexlib2.immutable.reference.ImmutableTypeReference("Landroid/media/session/MediaSession;")));ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction35c(org.jf.dexlib2.Opcode.INVOKE_DIRECT,3,0,8,9,0,0,new org.jf.dexlib2.immutable.reference.ImmutableMethodReference("Landroid/media/session/MediaSession;","<init>",params,"V")));ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction22c(org.jf.dexlib2.Opcode.IPUT_OBJECT,0,self,field));}else ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction22c(org.jf.dexlib2.Opcode.IPUT_OBJECT,9,self,field));ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction11n(org.jf.dexlib2.Opcode.CONST_4,self,3));ins.add(new org.jf.dexlib2.immutable.instruction.ImmutableInstruction10x(org.jf.dexlib2.Opcode.RETURN_VOID));constructors.add(new org.jf.dexlib2.immutable.ImmutableMethod(name,"<init>",args,"V",65537,Collections.emptySet(),Collections.emptySet(),new org.jf.dexlib2.immutable.ImmutableMethodImplementation(10,ins,Collections.emptyList(),Collections.emptyList())));
  }
  org.jf.dexlib2.iface.Field value=new org.jf.dexlib2.immutable.ImmutableField(name,"a","Landroid/media/session/MediaSession;",1,null,Collections.emptySet(),Collections.emptySet());org.jf.dexlib2.iface.ClassDef cls=new org.jf.dexlib2.immutable.ImmutableClassDef(name,1,"Ljava/lang/Object;",Collections.emptyList(),null,Collections.emptySet(),Collections.singletonList(value),constructors);org.jf.dexlib2.writer.io.MemoryDataStore store=new org.jf.dexlib2.writer.io.MemoryDataStore();org.jf.dexlib2.writer.pool.DexPool.writeTo(store,new org.jf.dexlib2.immutable.ImmutableDexFile(org.jf.dexlib2.Opcodes.forApi(24),Collections.singletonList(cls)));java.lang.reflect.Method hook=Class.forName("org.example.spotifymixer.engine.MediaHook").getDeclaredMethod("patch",byte[].class);hook.setAccessible(true);byte[][] output=(byte[][])hook.invoke(null,(Object)store.getData());java.io.File dex=java.io.File.createTempFile("own-media-hook-",".dex",context.getCodeCacheDir());java.nio.file.Files.write(dex.toPath(),output[1]);assertTrue(dex.setReadOnly());MediaSession session=fixture(new AtomicLong(),new AtomicInteger(),new AtomicInteger());try{ClassLoader loader=new dalvik.system.DexClassLoader(dex.getAbsolutePath(),context.getCodeCacheDir().getAbsolutePath(),null,context.getClassLoader());Class.forName("p.bqf0",true,loader).getConstructor(MediaSession.class).newInstance(session);until(()->MediaToolsRuntime.controller()!=null&&MediaToolsRuntime.controller().getSessionToken().equals(session.getSessionToken()));}finally{session.release();dex.delete();idle();}
 }
 @Test public void bookmarksAndSearchesPersistWithoutPlayback()throws Exception{
  AtomicLong sought=new AtomicLong(-1);AtomicInteger skips=new AtomicInteger();MediaSession session=fixture(sought,new AtomicInteger(),skips);
  try{MediaToolsRuntime.captureSession(session);until(()->ONE.equals(MediaToolsRuntime.currentTrack()));prefs.edit().putBoolean("bookmarks_enabled",true).putBoolean("saved_searches_enabled",true).commit();open("bookmarks");UiObject2 label=device.wait(Until.findObject(By.desc("Bookmark label")),3000);assertNotNull(label);label.setText("Guitar moment");text("Bookmark current moment").click();until(()->prefs.getString("track_bookmarks","").contains("Guitar moment"));text("Jump to saved moment").click();until(()->sought.get()==5000);assertEquals(0,skips.get());
   open("saved_searches");UiObject2 search=device.wait(Until.findObject(By.desc("Search phrase")),3000);assertNotNull(search);search.setText("instrumental & ambient");text("Save search").click();until(()->prefs.getString("saved_search_queries","").contains("instrumental & ambient"));open("saved_searches");text("instrumental & ambient");new SettingsProfiles(prefs).save("Safe profile");String profiles=prefs.getString("settings_profiles","");assertFalse(profiles.contains("Guitar moment"));assertFalse(profiles.contains("instrumental & ambient"));shot("21-bookmarks-saved-searches-own-fixture");
   prefs.edit().putBoolean("cinema_enabled",true).putBoolean("awake_enabled",true).commit();open("cinema");InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{});text("Own fixture song");open("details");text("Refresh track details");assertEquals(0,skips.get());
  }finally{session.release();idle();}
 }
 @Test public void catalogFlagsAreIndependentAndAmoledRestores(){Set<String> keys=new HashSet<>();for(FeatureCatalog.Feature f:FeatureCatalog.ALL){assertTrue(keys.add(f.key()));assertFalse(prefs.getBoolean(f.key(),false));}assertEquals(26,keys.size());prefs.edit().putBoolean("amoled_enabled",true).putBoolean("theme_enabled",true).putString("theme_preset","ocean").commit();ThemeRuntime.refresh(context);assertEquals(0xff000000,ThemeRuntime.mapColor(0xff121212));prefs.edit().putBoolean("amoled_enabled",false).commit();ThemeRuntime.refresh(context);assertEquals(ThemePalette.find("ocean").background,ThemeRuntime.mapColor(0xff121212));}
 @Test public void viewTweaksRestoreOwnRowsAndTrackLabels(){AtomicLong seek=new AtomicLong();MediaSession s=fixture(seek,new AtomicInteger(),new AtomicInteger());try{MediaToolsRuntime.captureSession(s);until(()->ONE.equals(MediaToolsRuntime.currentTrack()));try(ActivityScenario<FixtureActivity> scenario=ActivityScenario.launch(FixtureActivity.class)){scenario.onActivity(a->{OwnRecyclerView list=new OwnRecyclerView(a);LinearLayout row=new LinearLayout(a);row.setPadding(0,20,0,20);row.setMinimumHeight(100);TextView label=new TextView(a);label.setText("Own fixture song");label.setSingleLine(true);row.addView(label);list.addView(row,new LinearLayout.LayoutParams(-1,200));a.setContentView(list);prefs.edit().putBoolean("compact_enabled",true).putBoolean("track_info_enabled",true).commit();EnhancementRuntime.attach(a);EnhancementRuntime.refresh();assertEquals(160,row.getLayoutParams().height);assertEquals(10,row.getPaddingTop());assertEquals(3,label.getMaxLines());prefs.edit().putBoolean("compact_enabled",false).putBoolean("track_info_enabled",false).commit();EnhancementRuntime.refresh();assertEquals(200,row.getLayoutParams().height);assertEquals(20,row.getPaddingTop());assertEquals(1,label.getMaxLines());});}}finally{s.release();idle();}}
 public static final class OwnRecyclerView extends LinearLayout {OwnRecyclerView(Context c){super(c);setOrientation(1);}}
}
